// Starter file for Building AI-Powered Features in Applications
// Task instructions:
// Build an AI-powered blog assistant: summarise long articles, generate tags, suggest titles, and answer questions about content. Add rate limiting and ...

solution_code:
// services/aiService.js
import OpenAI from 'openai';
import { config } from '../config/index.js';

const openai = new OpenAI({ apiKey: config.openaiApiKey });

export const aiService = {
  async summarise(text, maxLength = 100) {
    const response = await openai.chat.completions.create({
      model: 'gpt-4o-mini',
      messages: [
        {
          role: 'system',
          content: `Summarise the following text in ${maxLength} words or fewer. Return only the summary.`
        },
        { role: 'user', content: text }
      ],
      max_tokens: maxLength * 2,
      temperature: 0.3
    });

    return response.choices[0].message.content;
  },

  async generateTags(content) {
    const response = await openai.chat.completions.create({
      model: 'gpt-4o-mini',
      messages: [
        {
          role: 'system',
          content: 'Extract 3-5 relevant tags from the content. Return as a JSON array of strings.'
        },
        { role: 'user', content }
      ],
      response_format: { type: 'json_object' },
      temperature: 0.2
    });

    return JSON.parse(response.choices[0].message.content).tags;
  },

  async chat(messages, context = '') {
    const systemMessage = context
      ? `You are a helpful assistant. Context: ${context}`
      : 'You are a helpful assistant.';

    const response = await openai.chat.completions.create({
      model: 'gpt-4o-mini',
      messages: [
        { role: 'system', content: systemMessage },
        ...messages
      ],
      temperature: 0.7,
      max_tokens: 1000
    });

    return response.choices[0].message.content;
  }
};
